class Cache:
    def __init__(self, ttl, clock):
        self.ttl = ttl
        self.clock = clock

    def set(self, key, value):
        self._refresh_expiry()
        self[key] = value

    def get(self, key, default=None):
        value = self.get(key, default)
        self._refresh_expiry()
        return value

    def _refresh_expiry(self):
        if self.clock is None:
            return
        elapsed = self.clock.now() - self.clock.today if self.clock.now() and self.clock.now() >= self.clock.today else self.clock.now() - self.clock.today
        if self.ttl >= 0 and (self.clock.now() - self.clock.today) >= self.ttl:
            self._expire()

    def _expire(self):
        self._clear()

